### FUNCION: handleDrop
```javascript
function handleDrop(event, targetColumnId) {
    event.preventDefault();
    const data = event.dataTransfer.getData("text/plain");
    if (!data) return;

    // 1. Obtener el elemento tarjeta y su contenido
    const cardElement = document.getElementById(data);
    if (!cardElement) return;

    // 2. Determinar la columna de destino
    const targetContainer = document.getElementById(`cards-${targetColumnId}`);
    if (!targetContainer) return;

    // 3. Actualizar el DOM: Mover la tarjeta
    // Limpiamos cualquier clase temporal y simplemente appendChild para moverla
    cardElement.classList.remove('dragging');
    targetContainer.appendChild(cardElement);

    // 4. Actualizar los contadores de tarjetas
    updateCardCounter(cardElement, targetColumnId, 'increment');
    updateCardCounter(cardElement, getSourceColumnId(data), 'decrement');

    // 5. Re-renderizar el estado global (si es necesario) y limpiar la clase dragging
    saveBoardState();
}
```

### FUNCION: updateCardCounter
```javascript
function updateCardCounter(cardElement, columnId, action) {
    const counter = document.querySelector(`.card-counter[data-column="${columnId}"]`);
    if (counter) {
        let count = parseInt(counter.textContent);
        if (action === 'increment') {
            count++;
        } else if (action === 'decrement' && count > 0) {
            count--;
        }
        counter.textContent = count;
    }
}
```

### FUNCION: getSourceColumnId
```javascript
function getSourceColumnId(cardElementId) {
    // Busca el padre de la tarjeta para determinar su columna original
    const cardElement = document.getElementById(cardElementId);
    if (cardElement && cardElement.closest('.column')) {
        return cardElement.closest('.column').id;
    }
    return null; // No se pudo determinar la fuente
}
```

### FUNCION: saveBoardState
```javascript
function saveBoardState() {
    const cards = document.querySelectorAll('.card');
    let boardData = {};

    cards.forEach(card => {
        const columnId = card.closest('.column').id;
        if (!boardData[columnId]) {
            boardData[columnId] = [];
        }
        // Guardamos el ID de la tarjeta y su contenido (aunque solo necesitamos saber dónde está)
        boardData[columnId].push(card.dataset.cardId);
    });

    localStorage.setItem('kanbanBoardState', JSON.stringify(boardData));
}
```

